import{_ as t,g as a,e as r,a4 as n}from"./chunks/framework.CEYJDsBW.js";const u=JSON.parse('{"title":"Sharing the Current Page","description":"","frontmatter":{},"headers":[],"relativePath":"en/ageratum/26.1/reader/share.md","filePath":"en/ageratum/26.1/reader/share.md"}'),o={name:"en/ageratum/26.1/reader/share.md"};function d(c,e,h,s,i,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="sharing-the-current-page" tabindex="-1">Sharing the Current Page <a class="header-anchor" href="#sharing-the-current-page" aria-label="Permalink to &quot;Sharing the Current Page&quot;">​</a></h1><p>When a player shares a guide, the client sends the page, anchor, and whether to share only with teammates. The server sends a clickable chat message to the selected players. When recipients click it, they open the file from their own client resource packs; the sender does not upload Markdown content.</p><table tabindex="0"><thead><tr><th><code>ShareGuidePayload</code> Field</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>location</code></td><td><code>Identifier</code></td><td>Namespace and file arguments used to generate the command.</td></tr><tr><td><code>anchor</code></td><td><code>String</code></td><td>If non-empty after trimming whitespace, appended as the third argument to the client command.</td></tr><tr><td><code>sameTeam</code></td><td><code>boolean</code></td><td>When <code>true</code>, filters recipients by team equality. Two players who are both not on any team are considered equal in this comparison.</td></tr></tbody></table><p>The server can send a request to open a guide, but cannot guarantee that the recipient&#39;s resource packs contain that page. For reliable jumps, ensure every client has the resource pack containing the page installed; to check in client code whether opening succeeded, read the boolean returned by the local open method. <a href="./../guides/open.html">Sending entrypoint</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/network/ServerPayloadHandler.java" target="_blank" rel="noreferrer">Share message handler</a></p>',4)])])}const m=t(o,[["render",d]]);export{u as __pageData,m as default};
